"""Ledger entries and the parser for the plain-text ledger format."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal, localcontext

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_SEPARATOR_RE = re.compile(r"[ \t]+")
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A line of the ledger is malformed. ``line`` is its 1-based number."""

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str


def parse_date(text):
    """Parse a strict ``YYYY-MM-DD`` string into a date; raise ValueError if invalid."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def parse_amount(text):
    """Parse an amount with at most two decimals into a Decimal."""
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError(
            "invalid amount %r (expected a number with at most two decimals)" % text
        )
    return Decimal(text)


def parse(text):
    """Parse ledger text into a list of Entry objects, in file order."""
    entries = []
    for number, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        fields = _SEPARATOR_RE.split(line, maxsplit=3)
        if len(fields) < 3:
            raise ParseError(
                number, "expected 'DATE CATEGORY AMOUNT [NOTE]', got %r" % line
            )
        date_text, category, amount_text = fields[:3]
        note = fields[3].strip() if len(fields) == 4 else ""
        try:
            date = parse_date(date_text)
            amount = parse_amount(amount_text)
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        entries.append(Entry(date, category.lower(), amount, note))
    return entries


def format_amount(amount):
    """Format an amount with exactly two decimals (never ``-0.00``)."""
    with localcontext() as ctx:
        ctx.prec = 1000
        cents = amount.quantize(_CENT)
    if not cents:
        cents = abs(cents)
    return str(cents)


def format_entry(entry):
    """Canonical ledger line for an entry (no trailing newline)."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
"""The ``pennywise`` command line interface."""

import argparse
import csv
import io
import json
import os
import re
import sys

from .ledger import ParseError, format_amount, format_entry, parse, parse_date
from .reports import balance, by_category, by_month, filter_entries

PROG = "pennywise"

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2


class _LedgerError(Exception):
    """A mistake in the ledger or in the entry given to ``add`` (exit 1)."""


class _Parser(argparse.ArgumentParser):
    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(EXIT_USAGE, "%s: %s\n" % (PROG, message))


def _date_arg(text):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    parser = _Parser(prog=PROG, description="Report where the money went from a plain-text ledger.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", parser_class=_Parser)
    commands.required = True

    p = commands.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = commands.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=("category", "month"), default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = commands.add_parser("list", help="print entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = commands.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = commands.add_parser("export", help="print entries as CSV, in list order")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=("csv",), default="csv")
    return parser


def _read_text(path):
    if path == "-":
        stream = sys.stdin
        data = stream.buffer.read() if hasattr(stream, "buffer") else stream.read()
    else:
        with open(path, "rb") as handle:
            data = handle.read()
    if isinstance(data, bytes):
        data = data.decode("utf-8-sig")
    return data


def _load(path):
    try:
        text = _read_text(path)
    except (OSError, UnicodeDecodeError) as exc:
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        raise OSError("cannot read %s: %s" % (path, reason)) from None
    try:
        return parse(text)
    except ParseError as exc:
        raise _LedgerError(str(exc)) from None


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)


def _as_json(value):
    return json.dumps(value) + "\n"


def _entry_dict(entry):
    return {
        "date": entry.date.isoformat(),
        "category": entry.category,
        "amount": format_amount(entry.amount),
        "note": entry.note,
    }


def _cmd_balance(args):
    total = format_amount(balance(_load(args.file)))
    return _as_json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_category(entries) if args.by == "category" else by_month(entries)
    rows = [(name, format_amount(totals[name])) for name in sorted(totals)]
    if args.json:
        return _as_json(dict(rows))
    return "".join("%s  %s\n" % row for row in rows)


def _cmd_list(args):
    entries = filter_entries(_load(args.file), args.category, args.since, args.until)
    entries = _sorted(entries)
    if args.json:
        return _as_json([_entry_dict(e) for e in entries])
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _sorted(_load(args.file))
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return out.getvalue()


def _cmd_add(args):
    for name, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or re.search(r"\s", value):
            raise _LedgerError("line 1: %s must be a single word, got %r" % (name, value))
    line = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note:
        line += " " + args.note
    if len(line.splitlines()) != 1:
        raise _LedgerError("line 1: note must not contain a line break")
    try:
        entries = parse(line)
    except ParseError as exc:
        raise _LedgerError(str(exc)) from None
    canonical = format_entry(entries[0])

    # Only touch the file once the entry is known to be valid.
    prefix = b""
    try:
        if os.path.getsize(args.file) > 0:
            with open(args.file, "rb") as handle:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
    except FileNotFoundError:
        pass
    with open(args.file, "ab") as handle:
        handle.write(prefix + canonical.encode("utf-8") + b"\n")
    return canonical + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv=None):
    """Run the CLI; return the process exit status."""
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE
    try:
        output = _COMMANDS[args.command](args)
    except _LedgerError as exc:
        sys.stderr.write("%s: %s\n" % (PROG, exc))
        return EXIT_LEDGER
    except OSError as exc:
        sys.stderr.write("%s: %s\n" % (PROG, exc))
        return EXIT_USAGE
    sys.stdout.write(output)
    return EXIT_OK
